<?php require_once __DIR__.'/_common.php'; $portalProfile=portal_profile($pdo); $pageTitle='Galeri Kegiatan'; $schemaReady=portal_schema_ready($pdo,'galeri_sekolah',['id','judul','keterangan','gambar_url','tanggal_kegiatan','status','created_at']); $items=$schemaReady ? portal_rows($pdo,"SELECT id,judul,keterangan,gambar_url,tanggal_kegiatan FROM galeri_sekolah WHERE status='Terbit' ORDER BY tanggal_kegiatan DESC,id DESC") : []; require __DIR__.'/_header.php'; ?>
<section class="page-hero"><div class="wrap"><span class="eyebrow">Momen sekolah</span><h1>Galeri Kegiatan</h1><p>Dokumentasi kegiatan dan pembelajaran <?= e($portalProfile['nama']) ?>.</p></div></section><section class="content"><div class="wrap"><?php if(!$schemaReady): ?><div class="schema-alert">Fitur galeri belum aktif karena migrasi database portal publik belum dijalankan. Minta administrator mengimpor <code>database/migrations/2026_10_29_public_portal.sql</code> ke database <code>sims_db</code>.</div><?php endif; ?><div class="cards"><?php if(!$items && $schemaReady): ?><div class="empty" style="grid-column:1/-1">Foto kegiatan akan tampil setelah dipilih dan diterbitkan oleh pengelola.</div><?php else: foreach($items as $g): $img=portal_image($g['gambar_url'],'galeri',(int)$g['id']); if(!$img)continue; ?><figure class="card story-card" style="margin:0"><img class="story-image" src="<?= e($img) ?>" alt="<?= e($g['judul']) ?>" loading="lazy"><figcaption class="story-body"><h3><?= e($g['judul']) ?></h3><p><?= e($g['keterangan']) ?><?= $g['tanggal_kegiatan'] ? ' · '.e(portal_date($g['tanggal_kegiatan'])) : '' ?></p></figcaption></figure><?php endforeach; endif; ?></div><p class="article-meta" style="margin-top:24px">Foto yang menampilkan siswa hanya boleh diterbitkan setelah sekolah memastikan persetujuan publikasi.</p></div></section><?php require __DIR__.'/_footer.php';
